    if (action === "bin-select-all") { target.closest("form")?.querySelectorAll("input[name='binSelected']")?.forEach((input) => { input.checked = true; }); return; }
    if (action === "bin-deselect-all") { target.closest("form")?.querySelectorAll("input[name='binSelected']")?.forEach((input) => { input.checked = false; }); return; }
