    if (action === "pause-activation") return runCommand(() => engine.commands.pauseActivation(id), "Activation paused.");
    if (action === "resume-activation") return runCommand(() => engine.commands.resumeActivation(id), "Activation resumed.");
    if (action === "set-primary-project") return runCommand(() => engine.commands.setPrimaryProject(id), "Primary Project selected."); if (action === "toggle-theme") { const current = documentRef.documentElement.dataset.theme || "light"; const next = current === "dark" ? "light" : "dark"; documentRef.documentElement.dataset.theme = next; return runCommand(() => engine.commands.updateSettings({ appearanceMode: next }), "Appearance saved."); } if (action === "export") return downloadBackup(); if (action === "restore-import") return runCommand(() => engine.commands.restoreLastImport(), "Previous state restored.");
